+{
+	(void)cpu_id;
+	(void)power_on;
+}
+int mb_ipc_cpu_is_power_on(u32 cpu_id)
+{
+	(void)cpu_id;
+
+	return 0;
+}
+int mb_ipc_cpu_is_power_off(u32 cpu_id)
+{
+	(void)cpu_id;
+
+	return 1;
+}
