+	if (ack_count >= MB_ACK_QUEUE_LEN)
+	{
+		phy_chnl_x_cb[destination].ack_queue_full_cnt++;
+		mb_chnl_exit_critical(flags);
+		return false;
+	}
+	entry = &ack_queue[ack_write];
+	entry->data = *data;
+	entry->destination = destination;
+	ack_write = (ack_write + 1) % MB_ACK_QUEUE_LEN;
+	ack_count++;
+	mb_chnl_exit_critical(flags);
+	mb_chnl_ack_retry();
+	return true;
