-	}
-
-	chnl_cb->tx_in_process = 1;
-
-	mb_uart_exit_critical(flag);
-
-	bk_err_t	ret_val = BK_FAIL;
-
-	ret_val = mb_uart_send_state(chnl_cb);
-
-	if(ret_val != BK_OK)
-	{
-		chnl_cb->tx_in_process = 0;  /* clear here, because no tx_cmpl_isr callback! */
-	}
-
-	return ret_val;
