+static bk_err_t mb_uart_send_data(mb_uart_cb_t *chnl_cb);
+static bk_err_t mb_uart_send_state(mb_uart_cb_t *chnl_cb);
+static bk_err_t mb_uart_send_data_trigger(mb_uart_cb_t *chnl_cb);
+
+static void mb_uart_notify(mb_uart_cb_t *chnl_cb, mb_uart_event_t event)
+{
+	u8 id = (chnl_cb->chnl_id == MB_CHNL_UART0) ? MB_UART0 : MB_UART1;
+
+	if (chnl_cb->event_callback)
+		chnl_cb->event_callback(id, event, chnl_cb->event_param);
+}
+
+static bool mb_uart_validate_command(mb_uart_cb_t *chnl_cb,
+				     mb_uart_cmd_t *uart_cmd, bool data)
+{
+	if (uart_cmd->resvd || uart_cmd->mb_cmd.param3)
+		return false;
+
+	if (data)
+	{
+		if (uart_cmd->cmd_buff != chnl_cb->rx_xchg_buff ||
+			uart_cmd->cmd_data_len < 1 ||
+			uart_cmd->cmd_data_len > UART_XCHG_DATA_MAX)
+			return false;
+		return uart_cmd->crc8 == cal_crc8_0x31((u8 *)uart_cmd->cmd_buff,
+							 uart_cmd->cmd_data_len);
+	}
+
+	return uart_cmd->cmd_buff == NULL && uart_cmd->cmd_data_len == 0 &&
+		uart_cmd->crc8 == 0;
+}
+
+static void rx_isr_data_handler(mb_uart_cb_t *chnl_cb, mb_uart_cmd_t * uart_cmd)
+{
+	u8      tx_fail = 0;
+
+	u16    rd_idx, wr_idx, free_cnt;
+
+	rd_idx = chnl_cb->rx_rd_idx;
+	wr_idx = chnl_cb->rx_wr_idx;
+
+	if(rd_idx > wr_idx)
+	{
+		free_cnt = rd_idx - wr_idx - 1;  // always reserved one byte space.
+	}
+	else
+	{
+		free_cnt = sizeof(chnl_cb->rx_buf) - (wr_idx - rd_idx) - 1;
+	}
+
+	if(!mb_uart_validate_command(chnl_cb, uart_cmd, true))
+	{
+		chnl_cb->status_error |= MB_UART_STATUS_PROTOCOL_ERR;
+		chnl_cb->bad_command_count++;
+		tx_fail = 1;
+		goto rx_isr_data_xit;
+	}
+
+	if(uart_cmd->cmd_data_len > free_cnt)
+	{
+		chnl_cb->status_overflow = 1;   /* discards all rx-data.  */
+		tx_fail = 1;
+
+		goto rx_isr_data_xit;
+	}
+
+	#if CONFIG_CACHE_ENABLE
+	flush_dcache(uart_cmd->cmd_buff, uart_cmd->cmd_data_len);
+	#endif
+
+	u16    rem_len, cpy_len;
+
+	cpy_len = uart_cmd->cmd_data_len;
+
+	if(wr_idx < rd_idx)
+	{
+		memcpy(chnl_cb->rx_buf + wr_idx, uart_cmd->cmd_buff, cpy_len);
+		chnl_cb->rx_wr_idx += cpy_len;
+	}
+	else
+	{
+		rem_len = sizeof(chnl_cb->rx_buf) - wr_idx;
+
+		if(rd_idx == 0)
+			rem_len -= 1;  // if rx_idx == 0, reserved one byte at tail of the array.
+
+		if(rem_len > cpy_len)
+		{
+			memcpy(chnl_cb->rx_buf + wr_idx, uart_cmd->cmd_buff, cpy_len);
+			chnl_cb->rx_wr_idx += cpy_len;
+		}
+		else
+		{
+			memcpy(chnl_cb->rx_buf + wr_idx, uart_cmd->cmd_buff, rem_len);
+
+			if(rem_len < cpy_len)
+			{
+				memcpy(chnl_cb->rx_buf, uart_cmd->cmd_buff + rem_len, cpy_len - rem_len);
+			}
+
+			chnl_cb->rx_wr_idx = cpy_len - rem_len;
+		}
+	}
+
+	free_cnt -= cpy_len;
+
+	if(chnl_cb->rx_isr_callback != NULL)
+	{
+		chnl_cb->rx_isr_callback(chnl_cb->rx_isr_param);
+	}
+
+rx_isr_data_xit:
+
+	if(free_cnt <= MB_UART_RX_FIFO_LEN)
+	{
+		chnl_cb->ctrl_rts = 1;
+	}
+
+	u8      old_cts = chnl_cb->status_cts;
+
+	chnl_cb->status_cts = uart_cmd->uart_rts;
+
+	/* overwrite the uart_cmd after the ISR handle completed.
+	 * return the rsp info to caller using the SAME buffer with cmd buffer.
+	 *     !!!! [input as param / output as result ]  !!!!
+	 */
+	u8 cmd = uart_cmd->chnl_hdr.cmd;
+	mb_uart_rsp_t * uart_rsp = (mb_uart_rsp_t *)uart_cmd;
+	memset(uart_rsp, 0, sizeof(*uart_rsp));
+	uart_rsp->chnl_hdr.cmd = cmd;
+	uart_rsp->uart_rts = chnl_cb->ctrl_rts;
+	uart_rsp->uart_tx_fail = tx_fail;
+	uart_rsp->resvd = 0;
+
+	if(chnl_cb->status_cts != old_cts)
+	{
+		if(chnl_cb->status_cts == 0)
+		{
+			/* trigger send! */
+			mb_uart_send_data_trigger(chnl_cb);
+		}
+	}
+
+	return;
+}
+
+static void rx_isr_state_handler(mb_uart_cb_t *chnl_cb, mb_uart_cmd_t *uart_cmd)
+{
+	u8      old_cts = chnl_cb->status_cts;
+	u8 cmd = uart_cmd->chnl_hdr.cmd;
+	u8 invalid = !mb_uart_validate_command(chnl_cb, uart_cmd, false);
+
+	if (!invalid)
+		chnl_cb->status_cts = uart_cmd->uart_rts;
+	else
+	{
+		chnl_cb->status_error |= MB_UART_STATUS_PROTOCOL_ERR;
+		chnl_cb->bad_command_count++;
+	}
+
+	/* overwrite the uart_cmd after the ISR handle completed.
+	 * return the rsp info to caller using the SAME buffer with cmd buffer.
+	 *     !!!! [input as param / output as result ]  !!!!
+	 */
+	mb_uart_rsp_t * uart_rsp = (mb_uart_rsp_t *)uart_cmd;
+	memset(uart_rsp, 0, sizeof(*uart_rsp));
+	uart_rsp->chnl_hdr.cmd = cmd;
+	uart_rsp->uart_rts = chnl_cb->ctrl_rts;
+	uart_rsp->uart_tx_fail = invalid;
+	uart_rsp->resvd = 0;
+
+	if(chnl_cb->status_cts != old_cts)
+	{
+		if(chnl_cb->status_cts == 0)
+		{
+			/* trigger send! */
+			mb_uart_send_data_trigger(chnl_cb);
+		}
+	}
+
+	return;
+}
+
+static void mb_uart_rx_isr(mb_uart_cb_t *chnl_cb, mb_chnl_cmd_t *cmd_buf)
+{
+	/* The response carries the current RTS state, but it cannot replace an
+	 * outstanding ACK-pool fence.
+	 */
+	if (!chnl_cb->tx_fence_req)
+		chnl_cb->tx_state_req = 0;
+
+	if(cmd_buf->hdr.cmd == MB_UART_SEND_DATA)
+	{
+		rx_isr_data_handler(chnl_cb, (mb_uart_cmd_t *)cmd_buf);
+	}
+	else if(cmd_buf->hdr.cmd == MB_UART_SEND_STATE)
+	{
+		rx_isr_state_handler(chnl_cb, (mb_uart_cmd_t *)cmd_buf);
+	}
+	else
+	{
+		/* overwrite the cmd_buf after the ISR handle completed.
+		 * return the ack info to caller using the SAME buffer with cmd buffer.
+		 *     !!!! [input as param / output as result ]  !!!!
+		 */
+		mb_uart_rsp_t * uart_rsp = (mb_uart_rsp_t *)cmd_buf;
+		u8 cmd = cmd_buf->hdr.cmd;
+		memset(uart_rsp, 0, sizeof(*uart_rsp));
+		uart_rsp->chnl_hdr.cmd = cmd;
+		uart_rsp->uart_rts = chnl_cb->ctrl_rts;
+		uart_rsp->uart_tx_fail = 1;
+		uart_rsp->resvd = 0;
+	}
+
+	return;
+}
+
+static void mb_uart_tx_cmpl_isr(mb_uart_cb_t *chnl_cb, mb_chnl_ack_t *ack_buf)  /* tx_cmpl_isr */
+{
+	mb_uart_rsp_t * uart_rsp = (mb_uart_rsp_t *)ack_buf;
+
+	u8      tx_fail = 0;
+
+	/* chnl_cb->rx_xchg_buff == uart_cmd->cmd_buff. MUST be true. */
+
+	if ((ack_buf->hdr.cmd != chnl_cb->tx_cmd) ||
+		(chnl_cb->tx_in_process == 0) )
+	{
+		chnl_cb->bad_ack_count++;
+		chnl_cb->status_error |= MB_UART_STATUS_PROTOCOL_ERR;
+		return;
+	}
+
+	chnl_cb->status_cts = uart_rsp->uart_rts;
+
+	if(ack_buf->hdr.state & CHNL_STATE_COM_FAIL)
+	{
+		tx_fail = 0x01;
+	}
+	else if ((uart_rsp->mb_ack.ack_data1 & ~0x3u) ||
+		 uart_rsp->mb_ack.ack_data2 || uart_rsp->mb_ack.ack_data3)
+	{
+		tx_fail = 1;
+		chnl_cb->status_error |= MB_UART_STATUS_PROTOCOL_ERR;
+	}
+	else
+	{
+		tx_fail = uart_rsp->uart_tx_fail;
+	}
+
+	if (!tx_fail && chnl_cb->tx_cmd == MB_UART_SEND_DATA)
+	{
+		chnl_cb->tx_rd_idx = (chnl_cb->tx_rd_idx + chnl_cb->tx_inflight_len) %
+					 sizeof(chnl_cb->tx_buf);
+		chnl_cb->tx_inflight_len = 0;
+		chnl_cb->tx_retry = 0;
+	}
+	else if (!tx_fail && chnl_cb->tx_cmd == MB_UART_SEND_STATE)
+	{
+		chnl_cb->tx_fence_req = 0;
+		if (!chnl_cb->link_ready)
+		{
+			chnl_cb->link_ready = 1;
+			chnl_cb->link_state = MB_UART_LINK_READY;
+			chnl_cb->probe_count = 0;
+			mb_chnl_recovered(GET_DST_CPU_ID(chnl_cb->chnl_id));
+			mb_uart_notify(chnl_cb, MB_UART_EVENT_READY);
+		}
+	}
+
+	if (tx_fail)
+	{
+		if (chnl_cb->tx_cmd == MB_UART_SEND_DATA)
+		{
+			if (chnl_cb->tx_retry)
+			{
+				chnl_cb->tx_rd_idx = (chnl_cb->tx_rd_idx +
+						      chnl_cb->tx_inflight_len) %
+						     sizeof(chnl_cb->tx_buf);
+				chnl_cb->tx_inflight_len = 0;
+				chnl_cb->tx_retry = 0;
+			}
+			else
+			{
+				chnl_cb->tx_retry = 1;
+			}
+		}
+		chnl_cb->status_error |= MB_UART_STATUS_TX_FAIL;
+		chnl_cb->link_ready = 0;
+		chnl_cb->tx_in_process = 0;
+		if (chnl_cb->probe_count < MB_UART_PROBE_MAX)
+		{
+			chnl_cb->link_state = MB_UART_LINK_PROBING;
+			chnl_cb->probe_due_ms = rtos_get_time() + MB_UART_PROBE_RETRY_MS;
+			chnl_cb->tx_state_req = 1;
+		}
+		else
+		{
+			chnl_cb->link_state = MB_UART_LINK_DOWN;
+			chnl_cb->tx_state_req = 0;
+			chnl_cb->probe_due_ms = rtos_get_time() +
+				MB_UART_DOWN_RETRY_MS;
+		}
+		mb_uart_notify(chnl_cb, MB_UART_EVENT_DOWN);
+		if (chnl_cb->tx_isr_callback)
+			chnl_cb->tx_isr_callback(chnl_cb->tx_isr_param);
+		return;
+	}
+
+	/* try next Tx. */
+
+	bk_err_t	ret_val = BK_FAIL;
+
+	if (chnl_cb->tx_state_req)
+	{
+		ret_val = mb_uart_send_state(chnl_cb);
+		if (ret_val == BK_OK)
+			chnl_cb->tx_state_req = 0;
+	}
+	if (ret_val != BK_OK)
+		ret_val = mb_uart_send_data(chnl_cb);
+
+	if(ret_val != BK_OK)
+	{
+		chnl_cb->tx_in_process = 0;  /* clear here, because no tx_cmpl_isr callback! */
+	}
+
+	if(chnl_cb->tx_isr_callback != NULL)
+	{
+		chnl_cb->tx_isr_callback(chnl_cb->tx_isr_param);
+	}
+
+	return;
+}
+
+static void mb_uart_channel_event(mb_uart_cb_t *chnl_cb, mb_chnl_event_t event)
+{
+	if (event == MB_CHNL_EVENT_RX_ACK_SENT)
+	{
+		u8 peer = GET_DST_CPU_ID(chnl_cb->chnl_id);
+
+		if (!chnl_cb->tx_fence_req &&
+			bk_mailbox_ack_slots_used((mailbox_endpoint_t)peer) >=
+			MB_UART_ACK_FENCE_WATERMARK)
+		{
+			chnl_cb->tx_fence_req = 1;
+			chnl_cb->tx_state_req = 1;
+		}
+	}
+	else if (event == MB_CHNL_EVENT_ABORT_SENT)
+	{
+		chnl_cb->link_ready = 0;
+		chnl_cb->link_state = MB_UART_LINK_PROBING;
+		chnl_cb->probe_count = 0;
+		chnl_cb->probe_due_ms = rtos_get_time();
+		chnl_cb->tx_state_req = 1;
+	}
+	else if (event == MB_CHNL_EVENT_ABORT_FAILED)
+	{
+		chnl_cb->link_ready = 0;
+		chnl_cb->link_state = MB_UART_LINK_DOWN;
+		chnl_cb->tx_state_req = 0;
+		mb_uart_notify(chnl_cb, MB_UART_EVENT_DOWN);
+	}
+	else
+	{
+		if (chnl_cb->tx_inflight_len)
+		{
+			/* Delivery is unknowable after a lost ACK. Drop this chunk instead
+			 * of replaying terminal input and making duplicate commands. */
+			chnl_cb->tx_rd_idx = (chnl_cb->tx_rd_idx +
+					      chnl_cb->tx_inflight_len) %
+					     sizeof(chnl_cb->tx_buf);
+			chnl_cb->tx_inflight_len = 0;
+			chnl_cb->tx_retry = 0;
+			chnl_cb->status_error |= MB_UART_STATUS_TX_FAIL;
+		}
+		chnl_cb->link_ready = 0;
+		chnl_cb->probe_count = 0;
+		chnl_cb->probe_due_ms = rtos_get_time();
+		chnl_cb->link_state = event == MB_CHNL_EVENT_TX_TIMEOUT ?
+			MB_UART_LINK_ABORTING : MB_UART_LINK_PROBING;
+		chnl_cb->tx_state_req = event == MB_CHNL_EVENT_PEER_RESET;
+		if (event == MB_CHNL_EVENT_PEER_RESET)
+			mb_uart_notify(chnl_cb, MB_UART_EVENT_PEER_RESET);
+		else
+			mb_uart_notify(chnl_cb, MB_UART_EVENT_TIMEOUT);
+	}
+
+	if (chnl_cb->tx_isr_callback)
+		chnl_cb->tx_isr_callback(chnl_cb->tx_isr_param);
+}
+
+static bk_err_t mb_uart_init(mb_uart_cb_t *chnl_cb, u8 chnl_id)
+{
+	bk_err_t		ret_code;
+
+	if(chnl_cb->chnl_inited)
+		return BK_OK;
+
+	memset(chnl_cb, 0, sizeof(mb_uart_cb_t));
+	chnl_cb->chnl_id = chnl_id;
+	chnl_cb->link_state = MB_UART_LINK_PROBING;
+	chnl_cb->tx_state_req = 1;
+
+	chnl_cb->tx_xchg_buff = mb_chnl_get_tx_buff(chnl_id);
+	chnl_cb->rx_xchg_buff = mb_chnl_get_rx_buff(chnl_id);
+
+	if( (chnl_cb->tx_xchg_buff == NULL) ||
+		(chnl_cb->rx_xchg_buff == NULL) )
+	{
+		return BK_FAIL;
+	}
+
+	ret_code = mb_chnl_open(chnl_id, chnl_cb);
+	if(ret_code != BK_OK)
+	{
+		return ret_code;
+	}
+
+	mb_chnl_ctrl(chnl_id, MB_CHNL_SET_RX_ISR, (void *)mb_uart_rx_isr);
+	mb_chnl_ctrl(chnl_id, MB_CHNL_SET_TX_CMPL_ISR, (void *)mb_uart_tx_cmpl_isr);
+	mb_chnl_ctrl(chnl_id, MB_CHNL_SET_TX_ISR, NULL);
+	mb_chnl_ctrl(chnl_id, MB_CHNL_SET_EVENT_ISR, (void *)mb_uart_channel_event);
+
+	chnl_cb->chnl_inited = 1;
+
+	return BK_OK;
+}
+
+static bk_err_t mb_uart_deinit(mb_uart_cb_t *chnl_cb, u8 chnl_id)
+{
+	if(!chnl_cb->chnl_inited)
+		return BK_OK;
+
+	mb_chnl_ctrl(chnl_id, MB_CHNL_SET_RX_ISR, NULL);
+	mb_chnl_ctrl(chnl_id, MB_CHNL_SET_TX_CMPL_ISR, NULL);
+	mb_chnl_ctrl(chnl_id, MB_CHNL_SET_TX_ISR, NULL);
+	mb_chnl_ctrl(chnl_id, MB_CHNL_SET_EVENT_ISR, NULL);
+
+	mb_chnl_close(chnl_id);
+
+	chnl_cb->rx_isr_callback = NULL;
+	chnl_cb->tx_isr_callback = NULL;
+
+	chnl_cb->chnl_inited = 0;
+
+	return BK_OK;
+}
+
+static bk_err_t mb_uart_send_data(mb_uart_cb_t *chnl_cb)
+{
+	bk_err_t	ret_val = BK_FAIL;
+
+	u16    rem_len, cpy_len;
+	u16    rd_idx, wr_idx;
+
+	if(chnl_cb->status_cts != 0)
+	{
+		return BK_ERR_BUSY;
+	}
+
+	rd_idx = chnl_cb->tx_rd_idx;
+	wr_idx = chnl_cb->tx_wr_idx;
+
+	if(rd_idx <= wr_idx)
+	{
+		cpy_len = wr_idx - rd_idx;
+	}
+	else
+	{
+		cpy_len = sizeof(chnl_cb->tx_buf) - (rd_idx - wr_idx);
+	}
+
+	if(cpy_len == 0)
+	{
+		return BK_FAIL;
+	}
+
+	if(cpy_len > MB_UART_TX_FIFO_LEN)
+	{
+		cpy_len = MB_UART_TX_FIFO_LEN;
+	}
+
+	if(rd_idx < wr_idx)
+	{
+		memcpy(chnl_cb->tx_xchg_buff, chnl_cb->tx_buf + rd_idx, cpy_len);
+	}
+	else
+	{
+		rem_len = sizeof(chnl_cb->tx_buf) - rd_idx;
+
+		if(rem_len >= cpy_len)
+		{
+			memcpy(chnl_cb->tx_xchg_buff, chnl_cb->tx_buf + rd_idx, cpy_len);
+		}
+		else
+		{
+			memcpy(chnl_cb->tx_xchg_buff, chnl_cb->tx_buf + rd_idx, rem_len);
+
+			memcpy(chnl_cb->tx_xchg_buff + rem_len, chnl_cb->tx_buf, cpy_len - rem_len);
+		}
+	}
+
+	chnl_cb->tx_cmd = MB_UART_SEND_DATA;
+
+	mb_uart_cmd_t	uart_cmd;
+
+	memset(&uart_cmd, 0, sizeof(uart_cmd));
+	uart_cmd.chnl_hdr.cmd  = MB_UART_SEND_DATA;
+	uart_cmd.cmd_buff      = (void *)(chnl_cb->tx_xchg_buff);
+	uart_cmd.cmd_data_len  = cpy_len;
+	uart_cmd.uart_rts      = chnl_cb->ctrl_rts;
+	uart_cmd.resvd         = 0;
+	uart_cmd.crc8          = cal_crc8_0x31(chnl_cb->tx_xchg_buff, cpy_len);
+
+	ret_val = mb_chnl_write(chnl_cb->chnl_id, (mb_chnl_cmd_t *)&uart_cmd);
+
+	if(ret_val == BK_OK)
+	{
+		chnl_cb->tx_inflight_len = cpy_len;
+	}
+
+	return ret_val;
+}
+
+static bk_err_t mb_uart_send_data_trigger(mb_uart_cb_t *chnl_cb)
+{
+	u32 flag = mb_uart_enter_critical();
+
+	if(chnl_cb->tx_in_process != 0)
+	{
+		mb_uart_exit_critical(flag);
+		return BK_OK;
+	}
+
+	chnl_cb->tx_in_process = 1;
+
+	mb_uart_exit_critical(flag);
+
+	bk_err_t	ret_val = BK_FAIL;
+
+	ret_val = mb_uart_send_data(chnl_cb);
+
+	if(ret_val != BK_OK)
+	{
+		chnl_cb->tx_in_process = 0;  /* clear here, because no tx_cmpl_isr callback! */
+	}
+
+	return ret_val;
+}
+
+static bk_err_t mb_uart_send_state(mb_uart_cb_t *chnl_cb)
+{
+	mb_uart_cmd_t	uart_cmd;
+
+	chnl_cb->tx_cmd = MB_UART_SEND_STATE;
+
+	memset(&uart_cmd, 0, sizeof(uart_cmd));
+	uart_cmd.chnl_hdr.cmd  = MB_UART_SEND_STATE;
+	uart_cmd.cmd_buff      = NULL;
+	uart_cmd.cmd_data_len  = 0;
+	uart_cmd.uart_rts      = chnl_cb->ctrl_rts;
+	uart_cmd.resvd         = 0;
+	uart_cmd.crc8          = 0;
+
+	bk_err_t	ret_val = BK_FAIL;
+
+	ret_val = mb_chnl_write(chnl_cb->chnl_id, (mb_chnl_cmd_t *)&uart_cmd);
+
+	return ret_val;
+}
+
+static bk_err_t mb_uart_send_state_trigger(mb_uart_cb_t *chnl_cb)
+{
+	u32 flag = mb_uart_enter_critical();
+
+	if(chnl_cb->tx_in_process != 0)
+	{
+		chnl_cb->tx_state_req = 1;
+		mb_uart_exit_critical(flag);
+		return BK_OK;
+	}
+
+	chnl_cb->tx_in_process = 1;
+
+	mb_uart_exit_critical(flag);
+
+	bk_err_t	ret_val = BK_FAIL;
+
+	ret_val = mb_uart_send_state(chnl_cb);
+
+	if(ret_val != BK_OK)
+	{
+		chnl_cb->tx_in_process = 0;  /* clear here, because no tx_cmpl_isr callback! */
+	}
+
+	return ret_val;
+}
+
+static u16 mb_uart_write_data(mb_uart_cb_t *chnl_cb, u8 * data_buf, u16 data_len)
+{
+	u16    rem_len, wr_len;
+	u16    rd_idx, wr_idx;
+
+	rd_idx = chnl_cb->tx_rd_idx;
+	wr_idx = chnl_cb->tx_wr_idx;
+
+	if(rd_idx > wr_idx)
+	{
+		rem_len = rd_idx - wr_idx - 1;  // always reserved one byte space.
+	}
+	else
+	{
+		rem_len = sizeof(chnl_cb->tx_buf) - (wr_idx - rd_idx) - 1;
+	}
+
+	wr_len = data_len;
+	if(wr_len > rem_len)
+		wr_len = rem_len;
+
+	if(wr_idx < rd_idx)
+	{
+		memcpy(chnl_cb->tx_buf + wr_idx, data_buf, wr_len);
+	}
+	else
+	{
+		if(rd_idx != 0)
+			rem_len = sizeof(chnl_cb->tx_buf) - wr_idx;  // if rx_idx == 0, reserved one byte at tail of the array.
+
+		if(rem_len >= wr_len)
+		{
+			memcpy(chnl_cb->tx_buf + wr_idx, data_buf, wr_len);
+		}
+		else
+		{
+			memcpy(chnl_cb->tx_buf + wr_idx, data_buf, rem_len);
+
+			memcpy(chnl_cb->tx_buf, data_buf + rem_len, wr_len - rem_len);
+		}
+	}
+
+	chnl_cb->tx_wr_idx = (wr_idx + wr_len) % sizeof(chnl_cb->tx_buf);
+
+	/* trigger send! */
+	mb_uart_send_data_trigger(chnl_cb);
+
+	return wr_len;
+}
+
+static u16 mb_uart_read_data(mb_uart_cb_t *chnl_cb, u8 * data_buf, u16 buf_len)
+{
+	u16    rem_len, rd_len;
+
+	if(!chnl_cb->chnl_inited)
+		return 0;
+
+	u16    rd_idx, wr_idx, data_cnt;
+
+	rd_idx = chnl_cb->rx_rd_idx;
+	wr_idx = chnl_cb->rx_wr_idx;
+
+	if(rd_idx <= wr_idx)
+	{
+		data_cnt = wr_idx - rd_idx;
+	}
+	else
+	{
+		data_cnt = sizeof(chnl_cb->rx_buf) - (rd_idx - wr_idx);
+	}
+
+	rd_len = data_cnt;
+	if(rd_len > buf_len)
+		rd_len = buf_len;
+
+	if(rd_len == 0)
+	{
+		return 0;
+	}
+
+	if(rd_idx < wr_idx)
+	{
+		memcpy(data_buf, chnl_cb->rx_buf + rd_idx, rd_len);
+		chnl_cb->rx_rd_idx += rd_len;
+	}
+	else
+	{
+		rem_len = sizeof(chnl_cb->rx_buf) - rd_idx;
+
+		if(rem_len > rd_len)
+		{
+			memcpy(data_buf, chnl_cb->rx_buf + rd_idx, rd_len);
+			chnl_cb->rx_rd_idx += rd_len;
+		}
+		else
+		{
+			memcpy(data_buf, chnl_cb->rx_buf + rd_idx, rem_len);
+			if(rem_len < rd_len)
+			{
+				memcpy(data_buf + rem_len, chnl_cb->rx_buf, rd_len - rem_len);
+			}
+
+			chnl_cb->rx_rd_idx = rd_len - rem_len;
+		}
+	}
+
+	data_cnt -= rd_len;
+
+	/* rts assert...... */
+	if(data_cnt < ((sizeof(chnl_cb->rx_buf) - 1 - MB_UART_RX_FIFO_LEN) * 8 / 10))
+	{
+		if( chnl_cb->ctrl_rts != 0)
+		{
+			chnl_cb->ctrl_rts = 0;
+			mb_uart_send_state_trigger(chnl_cb);
+		}
+	}
+
+	return rd_len;
+
+}
+
+/************************************************************************************
+ *
+ *             mb_uart_driver API
+ *
+ ************************************************************************************/
+
+static mb_uart_cb_t		mb_uart_cb[MB_UART_MAX] = {0};
+static const u8  		mb_uart_chnl_id[MB_UART_MAX] = {
+	MB_CHNL_UART0,
+	MB_CHNL_UART1
+};
+
+bk_err_t bk_mb_uart_dev_init(u8 id)
+{
+	bk_err_t    ret_val;
+
+	if(id >= MB_UART_MAX)
+		return BK_ERR_PARAM;
+
+	ret_val = mb_uart_init(&mb_uart_cb[id], mb_uart_chnl_id[id]);
+
+	if (ret_val == BK_OK)
+	{
+		mb_uart_cb[id].probe_count = 1;
+		mb_uart_send_state_trigger(&mb_uart_cb[id]);
+	}
+
+	return ret_val;
+}
+
+bk_err_t bk_mb_uart_dev_deinit(u8 id)
+{
+	bk_err_t    ret_val;
+
+	if(id >= MB_UART_MAX)
+		return BK_ERR_PARAM;
+
+	ret_val = mb_uart_deinit(&mb_uart_cb[id], mb_uart_chnl_id[id]);
+
+	return ret_val;
+}
+
+bk_err_t bk_mb_uart_register_rx_isr(u8 id, mb_uart_isr_t isr, void *param)
+{
+	if(id >= MB_UART_MAX)
+		return BK_ERR_PARAM;
+
+	if(!mb_uart_cb[id].chnl_inited)
+		return BK_ERR_NOT_INIT;
+
+	mb_uart_cb[id].rx_isr_param = param;    /* save rx_isr_param firstly! */
+	mb_uart_cb[id].rx_isr_callback = isr;
+
+	return BK_OK;
+}
+
+bk_err_t bk_mb_uart_register_tx_isr(u8 id, mb_uart_isr_t isr, void *param)
+{
+	if(id >= MB_UART_MAX)
+		return BK_ERR_PARAM;
+
+	if(!mb_uart_cb[id].chnl_inited)
+		return BK_ERR_NOT_INIT;
+
+	mb_uart_cb[id].tx_isr_param = param;    /* save tx_isr_param firstly! */
+	mb_uart_cb[id].tx_isr_callback = isr;
+
+	return BK_OK;
+}
+
+bk_err_t bk_mb_uart_register_event_callback(u8 id, mb_uart_event_cb_t callback,
+					    void *param)
+{
+	if (id >= MB_UART_MAX)
+		return BK_ERR_PARAM;
+	if (!mb_uart_cb[id].chnl_inited)
+		return BK_ERR_NOT_INIT;
+	mb_uart_cb[id].event_param = param;
+	mb_uart_cb[id].event_callback = callback;
+	return BK_OK;
+}
+
+void bk_mb_uart_poll(u8 id)
+{
+	if (id >= MB_UART_MAX || !mb_uart_cb[id].chnl_inited)
+		return;
+
+	mb_chnl_poll();
+	if (mb_uart_cb[id].link_state == MB_UART_LINK_DOWN &&
+		!mb_uart_cb[id].tx_in_process &&
+		(int32_t)(rtos_get_time() - mb_uart_cb[id].probe_due_ms) >= 0)
+	{
+		mb_uart_cb[id].probe_count = 0;
+		mb_uart_cb[id].link_state = MB_UART_LINK_PROBING;
+		mb_uart_cb[id].tx_state_req = 1;
+	}
+	if (!mb_uart_cb[id].tx_in_process && mb_uart_cb[id].tx_state_req)
+	{
+		if (mb_uart_cb[id].link_state == MB_UART_LINK_PROBING &&
+			(int32_t)(rtos_get_time() - mb_uart_cb[id].probe_due_ms) < 0)
+			return;
+		if (mb_uart_cb[id].probe_count >= MB_UART_PROBE_MAX)
+		{
+			mb_uart_cb[id].tx_state_req = 0;
+			mb_uart_cb[id].link_state = MB_UART_LINK_DOWN;
+			mb_uart_cb[id].probe_due_ms = rtos_get_time() +
+				MB_UART_DOWN_RETRY_MS;
+			return;
+		}
+		if (mb_uart_send_state_trigger(&mb_uart_cb[id]) == BK_OK)
+		{
+			mb_uart_cb[id].tx_state_req = 0;
+			mb_uart_cb[id].probe_count++;
+			if (!mb_uart_cb[id].link_ready)
+				mb_uart_cb[id].link_state = MB_UART_LINK_PROBING;
+		}
+	}
+}
+
+void bk_mb_uart_probe(u8 id)
+{
+	if (id >= MB_UART_MAX || !mb_uart_cb[id].chnl_inited)
+		return;
+
+	mb_uart_cb[id].link_ready = 0;
+	mb_uart_cb[id].link_state = MB_UART_LINK_PROBING;
+	mb_uart_cb[id].probe_count = 0;
+	mb_uart_cb[id].probe_due_ms = rtos_get_time();
+	mb_uart_cb[id].tx_state_req = 1;
+}
+
+mb_uart_link_state_t bk_mb_uart_get_link_state(u8 id)
+{
+	if (id >= MB_UART_MAX || !mb_uart_cb[id].chnl_inited)
+		return MB_UART_LINK_DOWN;
+	return (mb_uart_link_state_t)mb_uart_cb[id].link_state;
+}
+
+bool bk_mb_uart_is_link_ready(u8 id)
+{
+	return id < MB_UART_MAX && mb_uart_cb[id].chnl_inited &&
+		mb_uart_cb[id].link_ready && bk_mb_uart_write_ready(id) != 0;
+}
+
+u16 bk_mb_uart_write_ready(u8 id)
+{
+	if(id >= MB_UART_MAX)
+		return 0;
+
+	if(!mb_uart_cb[id].chnl_inited)
+		return 0;
+
+	u16    rem_len;
+	u16    rd_idx, wr_idx;
+
+	rd_idx = mb_uart_cb[id].tx_rd_idx;
+	wr_idx = mb_uart_cb[id].tx_wr_idx;
+
+	if(rd_idx > wr_idx)
+	{
+		rem_len = rd_idx - wr_idx - 1;  // always reserved one byte space.
+	}
+	else
+	{
+		rem_len = sizeof(mb_uart_cb[id].tx_buf) - (wr_idx - rd_idx) - 1;
+	}
+
+	return rem_len;
+}
+
+u16 bk_mb_uart_read_ready(u8 id)
+{
+	if(id >= MB_UART_MAX)
+		return 0;
+
+	if(!mb_uart_cb[id].chnl_inited)
+		return 0;
+
+	u16    rd_idx, wr_idx, data_cnt;
+
+	rd_idx = mb_uart_cb[id].rx_rd_idx;
+	wr_idx = mb_uart_cb[id].rx_wr_idx;
+
+	if(rd_idx <= wr_idx)
+	{
+		data_cnt = wr_idx - rd_idx;
+	}
+	else
+	{
+		data_cnt = sizeof(mb_uart_cb[id].rx_buf) - (rd_idx - wr_idx);
+	}
+
+	return data_cnt;
+}
+
+u16 bk_mb_uart_write_byte(u8 id, u8 data)
+{
+	u16     len;
+
+	if(id >= MB_UART_MAX)
+		return 0;
+
+	if(!mb_uart_cb[id].chnl_inited)
+		return 0;
+
+	len = mb_uart_write_data(&mb_uart_cb[id], &data, 1);
+
+	return len;
+}
+
+u16 bk_mb_uart_write(u8 id, u8 *data_buf, u16 data_len)
+{
+	u16     len;
+
+	if(id >= MB_UART_MAX)
+		return 0;
+
+	if(!mb_uart_cb[id].chnl_inited)
+		return 0;
+
+	if((data_buf == NULL) || (data_len == 0))
+		return 0;
+
+	len = mb_uart_write_data(&mb_uart_cb[id], data_buf, data_len);
+
+	return len;
+}
+
+u16 bk_mb_uart_read_byte(u8 id, u8 * data)
+{
+	u16     len;
+
+	if(id >= MB_UART_MAX)
+		return 0;
+
+	if(!mb_uart_cb[id].chnl_inited)
+		return 0;
+
+	if(data == NULL)
+		return 0;
+
+	len = mb_uart_read_data(&mb_uart_cb[id], data, 1);
+
+	return len;
+}
+
+u16 bk_mb_uart_read(u8 id, u8 *data_buf, u16 buf_len)
+{
+	u16     len;
+
+	if(id >= MB_UART_MAX)
+		return 0;
+
+	if(!mb_uart_cb[id].chnl_inited)
+		return 0;
+
+	if((data_buf == NULL) || (buf_len == 0))
+		return 0;
+
+	len = mb_uart_read_data(&mb_uart_cb[id], data_buf, buf_len);
+
+	return len;
+}
+
+bool bk_mb_uart_is_tx_over(u8 id)
+{
+	if(id >= MB_UART_MAX)
+		return 1;
+
+	if(!mb_uart_cb[id].chnl_inited)
+		return 1;
+
+	if( (mb_uart_cb[id].tx_rd_idx == mb_uart_cb[id].tx_wr_idx) &&
+		(mb_uart_cb[id].tx_in_process == 0) )
+	{
+		return 1;
+	}
+
+	return 0;
+}
+
+u16 bk_mb_uart_get_status(u8 id)
+{
+	u16    status = 0;
+
+	if(id >= MB_UART_MAX)
+		return 0;
+
+	if(!mb_uart_cb[id].chnl_inited)
+		return 0;
+
+	if(mb_uart_cb[id].status_overflow)
+	{
+		status |= MB_UART_STATUS_OVF;
+		mb_uart_cb[id].status_overflow = 0;
+	}
+
+	if(mb_uart_cb[id].status_parity)
+	{
+		status |= MB_UART_STATUS_PARITY_ERR;
+		mb_uart_cb[id].status_parity = 0;
+	}
+	status |= mb_uart_cb[id].status_error;
+	mb_uart_cb[id].status_error = 0;
+
+	return status;
+}
+
+#endif

diff --git a/cp/middleware/driver/common/driver.c b/cp/middleware/driver/common/driver.c
index 6e2ef5f..edd26ff 100755
--- a/cp/middleware/driver/common/driver.c
+++ b/cp/middleware/driver/common/driver.c
@@ -39,6 +39,492 @@
 #include <driver/pwr_clk.h>
 #include "bk_api_ipc.h"

+#if CONFIG_MAILBOX
+#include <driver/mb_uart_driver.h>
+#include <driver/mb_chnl_buff.h>
+#include <components/ap_console_bridge.h>
+#include <components/shell_task.h>
+#include "mbox0_adapter.h"
+
+#define AP_BRIDGE_TAG              "ap_bridge"
+#define AP_BRIDGE_TX_RING_SIZE     1024
+#define AP_BRIDGE_LOG_LINE_SIZE    256
+#define AP_BRIDGE_LOG_FLUSH_MS     50
+#define AP_BRIDGE_LOG_RETRY_MAX    3
+#define AP_BRIDGE_LOG_RETRY_MS     10
+#define AP_BRIDGE_EVENT_RX         0x01
+#define AP_BRIDGE_EVENT_TX         0x02
+#define AP_BRIDGE_EVENT_MODE       0x04
+#define AP_BRIDGE_EVENT_DOWN       0x08
+#define AP_BRIDGE_EVENT_RESET      0x10
+#define AP_BRIDGE_EVENT_TIMEOUT    0x20
+#define AP_BRIDGE_EVENT_READY      0x40
+#define AP_BRIDGE_EVENT_SYSTEM     0x80
+#define AP_BRIDGE_READY_ALL        (AP_BRIDGE_READY_MBUART | \
+				    AP_BRIDGE_READY_IPC | AP_BRIDGE_READY_PWC)
+#define AP_BRIDGE_MODE_TIMEOUT_MS  200
+
+typedef struct {
+	beken_semaphore_t sem;
+	beken_thread_t thread;
+	beken_mutex_t tx_mutex;
+	beken_semaphore_t mode_sem;
+	u8 tx_ring[AP_BRIDGE_TX_RING_SIZE];
+	u16 tx_rd;
+	u16 tx_wr;
+	volatile u32 events;
+	volatile u8 link_ready;
+	volatile u8 output_mode;
+	volatile u8 requested_mode;
+	volatile u8 ready_flags;
+	volatile u8 ready_set;
+	volatile u8 ready_clear;
+	volatile u32 mode_generation;
+	volatile u32 mode_applied_generation;
+	u32 last_down_log_ms;
+	ap_console_bridge_stats_t stats;
+} ap_bridge_cb_t;
+
+static ap_bridge_cb_t s_ap_bridge;
+
+static void ap_bridge_wake(u32 event)
+{
+	u32 flags = rtos_disable_int();
+	s_ap_bridge.events |= event;
+	rtos_enable_int(flags);
+	(void)rtos_set_semaphore(&s_ap_bridge.sem);
+}
+
+static void ap_bridge_mb_rx(void *param)
+{
+	(void)param;
+	ap_bridge_wake(AP_BRIDGE_EVENT_RX);
+}
+
+static void ap_bridge_mb_tx(void *param)
+{
+	(void)param;
+	ap_bridge_wake(AP_BRIDGE_EVENT_TX);
+}
+
+static void ap_bridge_mb_event(u8 id, mb_uart_event_t event, void *param)
+{
+	(void)id;
+	(void)param;
+
+	if (event == MB_UART_EVENT_READY)
+		ap_console_bridge_ready_update(AP_BRIDGE_READY_MBUART, true);
+	else if (event == MB_UART_EVENT_PEER_RESET)
+	{
+		ap_bridge_wake(AP_BRIDGE_EVENT_RESET);
+		ap_console_bridge_ready_update(AP_BRIDGE_READY_MBUART, false);
+	}
+	else if (event == MB_UART_EVENT_TIMEOUT)
+	{
+		ap_bridge_wake(AP_BRIDGE_EVENT_TIMEOUT);
+		ap_console_bridge_ready_update(AP_BRIDGE_READY_MBUART, false);
+	}
+	else
+	{
+		ap_bridge_wake(AP_BRIDGE_EVENT_DOWN);
+		ap_console_bridge_ready_update(AP_BRIDGE_READY_MBUART, false);
+	}
+}
+
+static void ap_bridge_log_output(const u8 *line, u16 length, bool prefix_line)
+{
+	static const u8 prefix[] = "ap0: ";
+	u8 output[sizeof(prefix) - 1 + AP_BRIDGE_LOG_LINE_SIZE];
+	u16 output_length;
+	u8 retry;
+
+	output_length = 0;
+	if (prefix_line)
+	{
+		memcpy(output, prefix, sizeof(prefix) - 1);
+		output_length = sizeof(prefix) - 1;
+	}
+	memcpy(output + output_length, line, length);
+	output_length += length;
+	for (retry = 0; retry < AP_BRIDGE_LOG_RETRY_MAX; retry++)
+	{
+		if (shell_log_raw_data(output, output_length))
+			return;
+		rtos_delay_milliseconds(AP_BRIDGE_LOG_RETRY_MS);
+	}
+	s_ap_bridge.stats.rx_queue_fail++;
+}
+
+static u16 ap_bridge_tx_count(void)
+{
+	if (s_ap_bridge.tx_rd <= s_ap_bridge.tx_wr)
+		return s_ap_bridge.tx_wr - s_ap_bridge.tx_rd;
+	return sizeof(s_ap_bridge.tx_ring) - (s_ap_bridge.tx_rd - s_ap_bridge.tx_wr);
+}
+
+static void ap_bridge_drain_tx(void)
+{
+	u8 data[MB_CHNL_BUFF_LEN];
+	u16 count;
+	u16 length;
+	u16 written;
+	u16 i;
+
+	while (s_ap_bridge.link_ready)
+	{
+		rtos_lock_mutex(&s_ap_bridge.tx_mutex);
+		count = ap_bridge_tx_count();
+		if (!count)
+		{
+			rtos_unlock_mutex(&s_ap_bridge.tx_mutex);
+			break;
+		}
+		length = MIN(count, (u16)sizeof(data));
+		length = MIN(length, bk_mb_uart_write_ready(MB_UART0));
+		if (!length)
+		{
+			rtos_unlock_mutex(&s_ap_bridge.tx_mutex);
+			break;
+		}
+
+		for (i = 0; i < length; i++)
+			data[i] = s_ap_bridge.tx_ring[(s_ap_bridge.tx_rd + i) %
+							 sizeof(s_ap_bridge.tx_ring)];
+
+		written = bk_mb_uart_write(MB_UART0, data, length);
+		if (!written)
+		{
+			rtos_unlock_mutex(&s_ap_bridge.tx_mutex);
+			break;
+		}
+		if (written < length)
+			s_ap_bridge.stats.tx_partial++;
+
+		s_ap_bridge.tx_rd = (s_ap_bridge.tx_rd + written) %
+					 sizeof(s_ap_bridge.tx_ring);
+		s_ap_bridge.stats.tx_bytes += written;
+		rtos_unlock_mutex(&s_ap_bridge.tx_mutex);
+	}
+}
+
+static void ap_bridge_task(beken_thread_arg_t arg)
+{
+	u8 input[MB_CHNL_BUFF_LEN];
+	u8 line[AP_BRIDGE_LOG_LINE_SIZE];
+	u16 line_length = 0;
+	u8 active_mode = AP_CONSOLE_OUTPUT_LOG;
+	bool line_continues = false;
+
+	(void)arg;
+	for (;;)
+	{
+		u32 events;
+		u32 flags;
+		u16 input_length;
+		u16 index;
+		u8 ready_set;
+		u8 ready_clear;
+		u8 ready_before;
+		bk_err_t ret = rtos_get_semaphore(&s_ap_bridge.sem,
+			line_length ? AP_BRIDGE_LOG_FLUSH_MS : 20);
+
+		bk_mb_uart_poll(MB_UART0);
+
+		flags = rtos_disable_int();
+		events = s_ap_bridge.events;
+		s_ap_bridge.events = 0;
+		ready_set = s_ap_bridge.ready_set;
+		ready_clear = s_ap_bridge.ready_clear;
+		ready_before = s_ap_bridge.ready_flags;
+		s_ap_bridge.ready_set = 0;
+		s_ap_bridge.ready_clear = 0;
+		rtos_enable_int(flags);
+
+		if (events & (AP_BRIDGE_EVENT_DOWN | AP_BRIDGE_EVENT_RESET |
+			      AP_BRIDGE_EVENT_TIMEOUT))
+		{
+			ready_clear |= AP_BRIDGE_READY_MBUART;
+		}
+		s_ap_bridge.ready_flags |= ready_set;
+		s_ap_bridge.ready_flags &= ~ready_clear;
+		/* poll() may complete recovery in the same iteration that consumes an
+		 * older timeout/reset event.  The driver's current state is the final
+		 * authority for the MBUART gate, so a stale event cannot clear a newer
+		 * READY notification permanently.
+		 */
+		if (bk_mb_uart_is_link_ready(MB_UART0))
+			s_ap_bridge.ready_flags |= AP_BRIDGE_READY_MBUART;
+		else
+			s_ap_bridge.ready_flags &= ~AP_BRIDGE_READY_MBUART;
+		s_ap_bridge.link_ready =
+			(s_ap_bridge.ready_flags & AP_BRIDGE_READY_ALL) ==
+			AP_BRIDGE_READY_ALL && bk_mb_uart_is_link_ready(MB_UART0);
+
+		if (s_ap_bridge.mode_applied_generation !=
+			s_ap_bridge.mode_generation)
+		{
+			if (line_length)
+				ap_bridge_log_output(line, line_length, !line_continues);
+			line_length = 0;
+			line_continues = false;
+			active_mode = s_ap_bridge.requested_mode;
+			s_ap_bridge.output_mode = active_mode;
+			s_ap_bridge.mode_applied_generation =
+				s_ap_bridge.mode_generation;
+			rtos_set_semaphore(&s_ap_bridge.mode_sem);
+		}
+
+		do
+		{
+			input_length = bk_mb_uart_read(MB_UART0, input, sizeof(input));
+			s_ap_bridge.stats.rx_bytes += input_length;
+			if (active_mode == AP_CONSOLE_OUTPUT_RAW)
+			{
+				if (input_length && !shell_log_raw_data(input, input_length))
+					s_ap_bridge.stats.rx_queue_fail++;
+				continue;
+			}
+
+			for (index = 0; index < input_length; index++)
+			{
+				line[line_length++] = input[index];
+				if (input[index] == '\n' || line_length == sizeof(line))
+				{
+					bool complete = input[index] == '\n';
+
+					ap_bridge_log_output(line, line_length,
+							     !line_continues);
+					line_length = 0;
+					line_continues = !complete;
+				}
+			}
+		} while (input_length != 0);
+
+		if (ret == kTimeoutErr && line_length &&
+			active_mode == AP_CONSOLE_OUTPUT_LOG)
+		{
+			ap_bridge_log_output(line, line_length, !line_continues);
+			line_length = 0;
+			line_continues = true;
+		}
+
+		ap_bridge_drain_tx();
+
+		if (events & (AP_BRIDGE_EVENT_DOWN | AP_BRIDGE_EVENT_RESET |
+			      AP_BRIDGE_EVENT_TIMEOUT))
+		{
+			u32 now = rtos_get_time();
+
+			s_ap_bridge.stats.link_down++;
+			if (events & AP_BRIDGE_EVENT_RESET)
+				s_ap_bridge.stats.reset++;
+			if (events & AP_BRIDGE_EVENT_TIMEOUT)
+				s_ap_bridge.stats.timeout++;
+			if ((ready_before & (AP_BRIDGE_READY_IPC |
+					     AP_BRIDGE_READY_PWC)) ==
+				(AP_BRIDGE_READY_IPC | AP_BRIDGE_READY_PWC) &&
+				(u32)(now - s_ap_bridge.last_down_log_ms) >= 1000)
+			{
+				s_ap_bridge.last_down_log_ms = now;
+				BK_LOGW(AP_BRIDGE_TAG,
+					"link down event=%x queued=%u ready=%x\r\n",
+					events, ap_bridge_tx_count(),
+					s_ap_bridge.ready_flags);
+			}
+			shell_ap_console_link_down();
+		}
+	}
+}
+
+bk_err_t ap_console_bridge_init(void)
+{
+	bk_err_t ret;
+
+	memset(&s_ap_bridge, 0, sizeof(s_ap_bridge));
+	ret = bk_pm_module_vote_sleep_ctrl(PM_SLEEP_MODULE_NAME_MAILBOX, 0, 0);
+	if (ret != BK_OK)
+		return ret;
+	ret = rtos_init_mutex(&s_ap_bridge.tx_mutex);
+	if (ret != BK_OK)
+		goto init_fail_vote;
+	ret = rtos_init_semaphore(&s_ap_bridge.sem, 1);
+	if (ret != BK_OK)
+		goto init_fail_mutex;
+	ret = rtos_init_semaphore(&s_ap_bridge.mode_sem, 1);
+	if (ret != BK_OK)
+		goto init_fail_sem;
+
+	ret = rtos_create_thread(&s_ap_bridge.thread,
+					 BEKEN_DEFAULT_WORKER_PRIORITY,
+					 "ap_console", ap_bridge_task, 3072, NULL);
+	if (ret != BK_OK)
+	{
+		rtos_deinit_semaphore(&s_ap_bridge.mode_sem);
+		rtos_deinit_semaphore(&s_ap_bridge.sem);
+		goto init_fail_mutex;
+	}
+
+	ret = bk_mb_uart_dev_init(MB_UART0);
+	if (ret != BK_OK)
+	{
+		rtos_delete_thread(&s_ap_bridge.thread);
+		rtos_deinit_semaphore(&s_ap_bridge.mode_sem);
+		rtos_deinit_semaphore(&s_ap_bridge.sem);
+		goto init_fail_mutex;
+	}
+
+	ret = bk_mb_uart_register_rx_isr(MB_UART0, ap_bridge_mb_rx, NULL);
+	if (ret == BK_OK)
+		ret = bk_mb_uart_register_tx_isr(MB_UART0, ap_bridge_mb_tx, NULL);
+	if (ret == BK_OK)
+		ret = bk_mb_uart_register_event_callback(MB_UART0, ap_bridge_mb_event, NULL);
+	if (ret != BK_OK)
+	{
+		bk_mb_uart_dev_deinit(MB_UART0);
+		rtos_delete_thread(&s_ap_bridge.thread);
+		rtos_deinit_semaphore(&s_ap_bridge.mode_sem);
+		rtos_deinit_semaphore(&s_ap_bridge.sem);
+		goto init_fail_mutex;
+	}
+
+	ap_bridge_wake(AP_BRIDGE_EVENT_RX | AP_BRIDGE_EVENT_TX);
+	BK_LOGI(AP_BRIDGE_TAG, "init owner=MB_UART0 tx_ring=%u mode=LOG\r\n",
+		(unsigned)sizeof(s_ap_bridge.tx_ring));
+	return BK_OK;
+
+init_fail_sem:
+	rtos_deinit_semaphore(&s_ap_bridge.sem);
+init_fail_mutex:
+	rtos_deinit_mutex(&s_ap_bridge.tx_mutex);
+init_fail_vote:
+	bk_pm_module_vote_sleep_ctrl(PM_SLEEP_MODULE_NAME_MAILBOX, 1, 0);
+	return ret;
+}
+
+u16 ap_console_bridge_write(const u8 *data, u16 length)
+{
+	u16 written = 0;
+
+	if (!data || !length || !s_ap_bridge.link_ready)
+		return 0;
+
+	rtos_lock_mutex(&s_ap_bridge.tx_mutex);
+	while (written < length)
+	{
+		u16 next = (s_ap_bridge.tx_wr + 1) % sizeof(s_ap_bridge.tx_ring);
+		if (next == s_ap_bridge.tx_rd)
+			break;
+		s_ap_bridge.tx_ring[s_ap_bridge.tx_wr] = data[written++];
+		s_ap_bridge.tx_wr = next;
+	}
+	rtos_unlock_mutex(&s_ap_bridge.tx_mutex);
+	if (written < length)
+	{
+		s_ap_bridge.stats.tx_drop += length - written;
+	}
+	if (written)
+		ap_bridge_wake(AP_BRIDGE_EVENT_TX);
+	return written;
+}
+
+void ap_console_bridge_purge_tx(void)
+{
+	rtos_lock_mutex(&s_ap_bridge.tx_mutex);
+	s_ap_bridge.stats.tx_drop += ap_bridge_tx_count();
+	s_ap_bridge.tx_rd = s_ap_bridge.tx_wr;
+	rtos_unlock_mutex(&s_ap_bridge.tx_mutex);
+}
+
+bk_err_t ap_console_bridge_set_output_mode(ap_console_output_mode_t mode)
+{
+	u32 generation;
+
+	if (mode > AP_CONSOLE_OUTPUT_RAW)
+		return BK_ERR_PARAM;
+	s_ap_bridge.requested_mode = mode;
+	generation = ++s_ap_bridge.mode_generation;
+	ap_bridge_wake(AP_BRIDGE_EVENT_MODE);
+	while (s_ap_bridge.mode_applied_generation != generation)
+	{
+		if (rtos_get_semaphore(&s_ap_bridge.mode_sem,
+				       AP_BRIDGE_MODE_TIMEOUT_MS) != BK_OK)
+			return BK_ERR_TIMEOUT;
+	}
+	return BK_OK;
+}
+
+bool ap_console_bridge_is_ready(void)
+{
+	return s_ap_bridge.link_ready;
+}
+
+void ap_console_bridge_get_stats(ap_console_bridge_stats_t *stats)
+{
+	mb_chnl_diag_t diag;
+	mbox0_adapter_diag_t adapter;
+
+	if (!stats)
+		return;
+	*stats = s_ap_bridge.stats;
+	rtos_lock_mutex(&s_ap_bridge.tx_mutex);
+	stats->tx_queued = ap_bridge_tx_count();
+	rtos_unlock_mutex(&s_ap_bridge.tx_mutex);
+	stats->mb_tx_free = bk_mb_uart_write_ready(MB_UART0);
+	stats->mb_rx_ready = bk_mb_uart_read_ready(MB_UART0);
+	stats->mb_status = bk_mb_uart_get_status(MB_UART0);
+	stats->link_ready = ap_console_bridge_is_ready();
+	stats->output_mode = s_ap_bridge.output_mode;
+	stats->ready_flags = s_ap_bridge.ready_flags;
+	stats->transport_state = bk_mb_uart_get_link_state(MB_UART0);
+	bk_mailbox_get_diag(&adapter);
+	stats->bad_envelope = adapter.bad_sid + adapter.bad_length +
+		adapter.bad_alignment + adapter.bad_address +
+		adapter.descriptor_overflow;
+	if (mb_chnl_get_diag(MAILBOX_CPU1, &diag) == BK_OK)
+	{
+		stats->active_busy = diag.busy;
+		stats->active_channel = diag.logical_chnl;
+		stats->active_sequence = diag.sequence;
+		stats->active_command = diag.command;
+		stats->ack_retry = diag.ack_retry;
+		stats->ack_queue_full = diag.ack_queue_full;
+		stats->reset_bad = diag.reset_bad;
+	}
+}
+
+void ap_console_bridge_ready_update(ap_console_ready_flag_t flag, bool ready)
+{
+	u32 flags = rtos_disable_int();
+
+	if (ready)
+	{
+		s_ap_bridge.ready_set |= flag;
+		s_ap_bridge.ready_clear &= ~flag;
+	}
+	else
+	{
+		s_ap_bridge.ready_clear |= flag;
+		s_ap_bridge.ready_set &= ~flag;
+		s_ap_bridge.link_ready = 0;
+	}
+	rtos_enable_int(flags);
+	if (ready && (flag & (AP_BRIDGE_READY_IPC | AP_BRIDGE_READY_PWC)) &&
+		!bk_mb_uart_is_link_ready(MB_UART0))
+		bk_mb_uart_probe(MB_UART0);
+	ap_bridge_wake(AP_BRIDGE_EVENT_SYSTEM);
+}
+
+void ap_console_bridge_link_down(void)
+{
+	u32 flags = rtos_disable_int();
+	s_ap_bridge.ready_clear |= AP_BRIDGE_READY_ALL;
+	s_ap_bridge.ready_set = 0;
+	s_ap_bridge.link_ready = 0;
+	rtos_enable_int(flags);
+	ap_bridge_wake(AP_BRIDGE_EVENT_DOWN | AP_BRIDGE_EVENT_SYSTEM);
+}
