+#if CONFIG_MAILBOX
+static void shell_ap_console_reset_parser(void)
+{
+	cmd_line_buf.cur_cmd_type = CMD_TYPE_INVALID;
+	cmd_line_buf.cmd_data_len = 0;
+	cmd_line_buf.bkreg_state = BKREG_WAIT_01;
+	cmd_line_buf.bkreg_left_byte = 0;
+	cmd_line_buf.cmd_ovf_hint = 0;
+	s_ap_escape_pending = 0;
+	cmd_dev->dev_drv->io_ctrl(cmd_dev, SHELL_IO_CTRL_RX_RESET, NULL);
+}
+
+static void shell_ap_console_switch_process(void)
+{
+	if (s_ap_link_down_request)
+	{
+		s_ap_link_down_request = 0;
+		s_ap_open_request = 0;
+		s_ap_close_request = 0;
+		if (s_uart0_owner != UART0_OWNER_CP_CLI)
+		{
+			s_uart0_owner = UART0_OWNER_TO_CP_PENDING;
+			ap_console_bridge_purge_tx();
+			(void)ap_console_bridge_set_output_mode(AP_CONSOLE_OUTPUT_LOG);
+			shell_set_log_level(s_ap_saved_log_level);
+			shell_ap_console_reset_parser();
+			s_uart0_owner = UART0_OWNER_CP_CLI;
+			shell_log_raw_data((const u8 *)"\r\nAP link down; returned to CP CLI\r\n$",
+					   sizeof("\r\nAP link down; returned to CP CLI\r\n$") - 1);
+		}
+		return;
+	}
+
+	if (s_ap_close_request)
+	{
+		s_ap_close_request = 0;
+		s_ap_open_request = 0;
+		if (s_uart0_owner == UART0_OWNER_AP_CONSOLE)
+		{
+			ap_console_bridge_stats_t stats;
+			s_uart0_owner = UART0_OWNER_TO_CP_PENDING;
+			ap_console_bridge_purge_tx();
+			(void)ap_console_bridge_set_output_mode(AP_CONSOLE_OUTPUT_LOG);
+			shell_set_log_level(s_ap_saved_log_level);
+			shell_ap_console_reset_parser();
+			s_uart0_owner = UART0_OWNER_CP_CLI;
+			ap_console_bridge_get_stats(&stats);
+			shell_cmd_ind_out("AP console input drops: %u\r\n",
+					  (unsigned)(stats.tx_drop - s_ap_open_drop));
+			shell_log_raw_data((const u8 *)"\r\nAP console closed\r\n$",
+					   sizeof("\r\nAP console closed\r\n$") - 1);
+		}
+		return;
+	}
+
+	if (s_ap_open_request)
+	{
+		ap_console_bridge_stats_t stats;
+
+		s_ap_open_request = 0;
+		s_uart0_owner = UART0_OWNER_TO_AP_PENDING;
+		if (!ap_console_bridge_is_ready())
+		{
+			s_uart0_owner = UART0_OWNER_CP_CLI;
+			shell_log_raw_data((const u8 *)"\r\nAP console unavailable\r\n$",
+					   sizeof("\r\nAP console unavailable\r\n$") - 1);
+			return;
+		}
+
+		shell_ap_console_reset_parser();
+		if (ap_console_bridge_set_output_mode(AP_CONSOLE_OUTPUT_RAW) != BK_OK)
+		{
+			s_uart0_owner = UART0_OWNER_CP_CLI;
+			shell_log_raw_data((const u8 *)"\r\nAP console mode switch timeout\r\n$",
+					   sizeof("\r\nAP console mode switch timeout\r\n$") - 1);
+			return;
+		}
+		s_ap_saved_log_level = shell_get_log_level();
+		shell_set_log_level(BK_LOG_ERROR);
+		ap_console_bridge_get_stats(&stats);
+		s_ap_open_drop = stats.tx_drop;
+		s_uart0_owner = UART0_OWNER_AP_CONSOLE;
+		shell_log_raw_data((const u8 *)"\r\nAP console open; exit with Ctrl-], release, then press .\r\n",
+				   sizeof("\r\nAP console open; exit with Ctrl-], release, then press .\r\n") - 1);
+	}
+}
+
+void shell_ap_console_link_down(void)
+{
+	if (s_uart0_owner == UART0_OWNER_AP_CONSOLE ||
+		s_uart0_owner == UART0_OWNER_TO_AP_PENDING)
+	{
+		s_ap_link_down_request = 1;
+		set_shell_event(&shell_task_event, SHELL_EVENT_AP_SWITCH);
+	}
+}
+
+void shell_ap_console_command(char *pcWriteBuffer, int xWriteBufferLen,
+				      int argc, char **argv)
+{
+	ap_console_bridge_stats_t stats;
+
+	if (argc != 2)
+	{
+		snprintf(pcWriteBuffer, xWriteBufferLen,
+			 "usage: ap_console open|close|status\r\n");
+		return;
+	}
+
+	if (!strcmp(argv[1], "open"))
+	{
+		if (s_uart0_owner != UART0_OWNER_CP_CLI)
+			snprintf(pcWriteBuffer, xWriteBufferLen, "AP console busy\r\n");
+		else if (!ap_console_bridge_is_ready())
+			snprintf(pcWriteBuffer, xWriteBufferLen,
+				 "AP console link not ready\r\n");
+		else
+		{
+			s_ap_open_request = 1;
+			snprintf(pcWriteBuffer, xWriteBufferLen,
+				 "switching UART0 to AP console...\r\n");
+		}
+		return;
+	}
+
+	if (!strcmp(argv[1], "close"))
+	{
+		if (s_uart0_owner == UART0_OWNER_AP_CONSOLE)
+		{
+			s_ap_close_request = 1;
+			set_shell_event(&shell_task_event, SHELL_EVENT_AP_SWITCH);
+		}
+		snprintf(pcWriteBuffer, xWriteBufferLen,
+			 s_uart0_owner == UART0_OWNER_CP_CLI ?
+			 "AP console already closed\r\n" : "AP console closing\r\n");
+		return;
+	}
+
+	if (strcmp(argv[1], "status"))
+	{
+		snprintf(pcWriteBuffer, xWriteBufferLen,
+			 "usage: ap_console open|close|status\r\n");
+		return;
+	}
+
+	ap_console_bridge_get_stats(&stats);
+	shell_cmd_ind_out("bridge rx=%u tx=%u drop=%u part=%u qfail=%u "
+			  "down=%u reset=%u timeout=%u st=%x\r\n",
+			  (unsigned)stats.rx_bytes, (unsigned)stats.tx_bytes,
+			  (unsigned)stats.tx_drop, (unsigned)stats.tx_partial,
+			  (unsigned)stats.rx_queue_fail, (unsigned)stats.link_down,
+		 (unsigned)stats.reset, (unsigned)stats.timeout,
+		 stats.mb_status);
+	shell_cmd_ind_out("ready=0x%x state=%u badenv=%u ackretry=%u ackfull=%u badreset=%u\r\n",
+			  stats.ready_flags, stats.transport_state,
+			  (unsigned)stats.bad_envelope, (unsigned)stats.ack_retry,
+			  (unsigned)stats.ack_queue_full, (unsigned)stats.reset_bad);
+	snprintf(pcWriteBuffer, xWriteBufferLen,
+		 "owner=%s link=%s mode=%s q=%u free=%u mbrx=%u active=%u/%x/%u/%u\r\n",
+		 s_uart0_owner == UART0_OWNER_CP_CLI ? "CP_CLI" :
+		 s_uart0_owner == UART0_OWNER_AP_CONSOLE ? "AP_CONSOLE" : "PENDING",
+		 stats.link_ready ? "ready" : "down",
+		 stats.output_mode == AP_CONSOLE_OUTPUT_RAW ? "RAW" : "LOG",
+		 stats.tx_queued, stats.mb_tx_free, stats.mb_rx_ready,
+		 stats.active_busy, stats.active_channel, stats.active_sequence,
+		 stats.active_command);
+}
+#endif
